// 스터디 확정 요청 검증
// - 인원: 최소 2명, 최대 4명
// - 이메일: @skuniv.ac.kr 로 끝나야 함 (학생 전용)
const MIN_MEMBERS = 2;
const MAX_MEMBERS = 4;
const EMAIL_RE = /^[A-Za-z0-9._%+-]+@skuniv\.ac\.kr$/i;

const body = $input.first().json.body ?? {};
const errors = [];

const studyId = body.studyId ?? null;
const studyTitle = typeof body.studyTitle === 'string' ? body.studyTitle.trim() : '';
if (!studyTitle) errors.push('studyTitle(스터디 이름)이 필요합니다.');

const rawMembers = Array.isArray(body.members) ? body.members : null;
if (!rawMembers) errors.push('members 배열이 필요합니다.');

const members = [];
const seen = new Set();
(rawMembers ?? []).forEach((m, i) => {
  const name = typeof m?.name === 'string' ? m.name.trim() : '';
  const email = typeof m?.email === 'string' ? m.email.trim().toLowerCase() : '';
  if (!name) errors.push(`members[${i}]: 이름이 비어 있습니다.`);
  if (!EMAIL_RE.test(email)) {
    errors.push(`members[${i}]: '${email || '(빈 값)'}' 은(는) @skuniv.ac.kr 학교 메일이 아닙니다.`);
  } else if (seen.has(email)) {
    errors.push(`members[${i}]: '${email}' 이메일이 중복되었습니다.`);
  }
  seen.add(email);
  members.push({ name, email });
});

if (rawMembers && (members.length < MIN_MEMBERS || members.length > MAX_MEMBERS)) {
  errors.push(`스터디 인원은 ${MIN_MEMBERS}~${MAX_MEMBERS}명이어야 합니다. (현재 ${members.length}명)`);
}

return [{ json: { valid: errors.length === 0, errors, studyId, studyTitle, members } }];

// 스터디원 한 명당 메일 1통: 전체 명단(이름 + 이메일)을 담아 보냄
const { studyId, studyTitle, members } = $input.first().json;

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const rows = members.map((m, i) =>
  `<tr><td style="padding:6px 12px;border:1px solid #ddd;">${i + 1}</td>` +
  `<td style="padding:6px 12px;border:1px solid #ddd;">${esc(m.name)}</td>` +
  `<td style="padding:6px 12px;border:1px solid #ddd;"><a href="mailto:${esc(m.email)}">${esc(m.email)}</a></td></tr>`
).join('');

return members.map((me) => ({
  json: {
    studyId,
    studyTitle,
    to: me.email,
    subject: `[SKU 스터디] '${studyTitle}' 스터디 인원이 확정되었습니다`,
    html:
      `<p>${esc(me.name)}님, 안녕하세요.</p>` +
      `<p><b>${esc(studyTitle)}</b> 스터디 인원(${members.length}명)이 확정되었습니다.<br>` +
      `아래 스터디원들에게 연락해 첫 모임 일정을 정해 보세요.</p>` +
      `<table style="border-collapse:collapse;font-size:14px;">` +
      `<tr style="background:#f3f4f6;"><th style="padding:6px 12px;border:1px solid #ddd;">#</th>` +
      `<th style="padding:6px 12px;border:1px solid #ddd;">이름</th>` +
      `<th style="padding:6px 12px;border:1px solid #ddd;">이메일</th></tr>` +
      rows + `</table>` +
      `<p style="color:#888;font-size:12px;">본 메일은 SKU 스터디 커뮤니티에서 자동 발송되었습니다.</p>`,
  },
}));

const src = $('메일 내용 만들기').all();
return [{
  json: {
    success: true,
    studyId: src[0]?.json.studyId ?? null,
    studyTitle: src[0]?.json.studyTitle ?? '',
    sentCount: $input.all().length,
    recipients: src.map((i) => i.json.to),
  },
}];
